// Independent full Q4 N14 optional-neighbor spectrum enumeration.
#include <bits/stdc++.h>
using namespace std;using E=vector<pair<int,int>>;int omitted;E F,cur;vector<E>N;array<int,16>mate;map<int,long long>hist;long long input_count;vector<E>worst;
void shortpm(unsigned m){if(!m){N.push_back(cur);return;}int a=__builtin_ctz(m);m^=1u<<a;for(int j=0;j<4;j++){int b=a^(1<<j);if(m>>b&1){cur.push_back({a,b});shortpm(m^(1u<<b));cur.pop_back();}}}
void assess(){unsigned spectrum=0;for(auto&n:N){int adj[16][2],deg[16]{};bool ok=true;for(auto[a,b]:F){adj[a][deg[a]++]=b;adj[b][deg[b]++]=a;}for(auto[a,b]:n){if(mate[a]==b){ok=false;break;}adj[a][deg[a]++]=b;adj[b][deg[b]++]=a;}if(!ok)continue;unsigned seen=0;int p=-1,v=0;while(!(seen>>v&1)){seen|=1u<<v;int next=adj[v][0]==p?adj[v][1]:adj[v][0];p=v;v=next;}if(v!=0||seen!=(65535u&~(1u<<omitted)))continue;for(int b:adj[0])spectrum|=1u<<b;}hist[__builtin_popcount(spectrum)]++;input_count++;if(__builtin_popcount(spectrum)==3&&worst.size()<3)worst.push_back(F);}
void pairall(unsigned m){if(!m){assess();return;}int a=__builtin_ctz(m);m^=1u<<a;for(int b=a+1;b<16;b++)if(m>>b&1){F.push_back({a,b});mate[a]=b;mate[b]=a;pairall(m^(1u<<b));F.pop_back();mate[a]=mate[b]=-1;}}
int main(){cout<<"[";bool sep=false;for(int h:{3,15}){omitted=h;N.clear();hist.clear();input_count=0;worst.clear();for(int i=0;i<4;i++)for(int j=i+1;j<4;j++){int a=1<<i,b=1<<j;cur={{0,a},{0,b}};shortpm(65534u&~(1u<<omitted)&~(1u<<a)&~(1u<<b));}mate.fill(-1);pairall(65534u&~(1u<<omitted));assert(input_count==135135&&hist.begin()->first==3&&hist[3]==(h==3?208:212));if(sep)cout<<",";sep=true;cout<<"{\"status\":\"PASS\",\"free\":0,\"omitted\":"<<h<<",\"matchings\":"<<input_count<<",\"degree_patterns\":"<<N.size()<<",\"neighbor_union_size_histogram\":{";bool t=false;for(auto[k,n]:hist){if(t)cout<<",";t=true;cout<<"\""<<k<<"\":"<<n;}cout<<"}}";}cout<<"]\n";}
